use vstd::prelude::*;

verus! {
    /// A pure specification of sequence‐reverse on immutable `Seq<char>`.
    spec fn rev_seq(s: Seq<char>) -> Seq<char>
        decreases s.len()
    {
        if s.len() == 0 {
            Seq::empty()
        } else {
            let last = s.index(s.len() - 1);
            rev_seq(s.slice(0, s.len() - 1)).push_back(last)
        }
    }

    /// The verified imperative reverse.
    fn reverse(a: &Vec<char>) -> (result: Vec<char>)
        ensures
            // at return, `result.view()` is exactly the pure `rev_seq(a.view())`
            result.view() == rev_seq(a.view()),
    {
        let n = a.len();
        let mut b = Vec::with_capacity(n);

        // We iterate i = n-1, n-2, …, 0.
        for i in (0..n).rev()
            invariant
                // never grow past n
                b.len() <= n,
                // at each step, b.view() is a prefix of rev_seq(a.view())
                forall k: usize :: k < b.len() ==> b.view()[k] == rev_seq(a.view())[k],
            decreases
                // measure the remaining iterations by i
                i,
        {
            b.push(a[i]);
        }

        // return the fully-built reversed vector
        b
    }
}

